"""Sequential preservation runs; prior transfer is consumed evidence, never fresh."""
import argparse,subprocess,sys
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1];sys.path.insert(0,str(ROOT))
from tools.cryptid_trial import read,save,sha
from tools.bubble_wrap_trial import normal
COHORTS=[('mothman-development','cryptid_trial.py','evaluation/cryptid/mothman/development','evaluation/cryptid/mothman/runs/candidate-5'),('mothman-first','cryptid_replay_packet.py','evaluation/cryptid/mothman/consumed-transfer','evaluation/cryptid/mothman/runs/consumed-development-c5'),('mothman-fresh','cryptid_replay_packet.py','evaluation/cryptid/mothman/fresh/consumed-transfer','evaluation/cryptid/mothman/runs/fresh-transfer-once'),('jackalope-development','cryptid_trial_v2.py','evaluation/cryptid/jackalope/development','evaluation/cryptid/nessie/prior-current/jackalope-development'),('jackalope-transfer','cryptid_replay_packet_v2.py','evaluation/cryptid/jackalope/consumed-transfer','evaluation/cryptid/nessie/prior-current/jackalope-transfer'),('yeti-development','cryptid_trial_v3.py','evaluation/cryptid/yeti/development','evaluation/cryptid/nessie/prior-current/yeti-development'),('yeti-wrap','cryptid_trial_v3.py','evaluation/cryptid/yeti/wrap','evaluation/cryptid/yeti/runs/wrap-candidate-2'),('yeti-transfer','cryptid_replay_packet_v3.py','evaluation/cryptid/yeti/consumed-transfer','evaluation/cryptid/nessie/prior-current/yeti-transfer'),('sasquatch-development','cryptid_trial_v3.py','evaluation/cryptid/sasquatch/development','evaluation/cryptid/sasquatch/runs/candidate-1'),('sasquatch-transfer','cryptid_replay_packet_v3.py','evaluation/cryptid/sasquatch/consumed-transfer','evaluation/cryptid/sasquatch/runs/transfer-once'),('chupacabra-development','cryptid_trial_v3.py','evaluation/cryptid/chupacabra/development','evaluation/cryptid/chupacabra/runs/candidate-2'),('chupacabra-transfer','cryptid_replay_packet_v3.py','evaluation/cryptid/chupacabra/consumed-transfer','evaluation/cryptid/chupacabra/runs/transfer-once'),('chupacabra-structural','cryptid_replay_packet_v3.py','evaluation/cryptid/chupacabra/fresh/consumed-transfer','evaluation/cryptid/chupacabra/runs/fresh-transfer-once'),('kraken-development','cryptid_trial_v3.py','evaluation/cryptid/kraken/development','evaluation/cryptid/kraken/runs/candidate-2'),('kraken-first','cryptid_replay_packet_v3.py','evaluation/cryptid/kraken/consumed-transfer','evaluation/cryptid/kraken/runs/consumed-development-c2'),('kraken-policy','cryptid_trial_v4.py','evaluation/cryptid/kraken/wrap','evaluation/cryptid/kraken/runs/policy-candidate-2'),('kraken-fresh','cryptid_replay_packet_v4.py','evaluation/cryptid/kraken/fresh/consumed-transfer','evaluation/cryptid/kraken/runs/fresh-transfer-once'),('nessie-development','cryptid_trial_v5.py','evaluation/cryptid/nessie/development','evaluation/cryptid/nessie/runs/automatic-candidate-5'),('nessie-governors','cryptid_trial_v5.py','evaluation/cryptid/nessie/wrap','evaluation/cryptid/nessie/runs/governors-candidate-5'),('nessie-conditions','cryptid_trial_v5.py','evaluation/cryptid/nessie/condition-wrap','evaluation/cryptid/nessie/runs/conditions-candidate-5'),('nessie-roles','cryptid_trial_v5.py','evaluation/cryptid/nessie/role-wrap','evaluation/cryptid/nessie/runs/roles-candidate-5'),('nessie-signers','cryptid_trial_v5.py','evaluation/cryptid/nessie/signer-wrap','evaluation/cryptid/nessie/runs/signers-candidate-5'),('nessie-transfer','cryptid_replay_packet_v5.py','evaluation/cryptid/nessie/consumed-transfer','evaluation/cryptid/nessie/runs/transfer-once')]
def main(a):
    a.output.mkdir(parents=True,exist_ok=False);rows=[]
    for name,tool,packet,before in COHORTS:
        before=ROOT/before
        if not (before/'run.json').exists():raise ValueError('Missing prior reference '+str(before))
        flag='--packet' if 'replay' in tool else '--registry';arg=packet if flag=='--packet' else packet+'/registry.json'
        command=[sys.executable,'tools/'+tool,flag,arg,'--implementation',str(a.implementation.resolve()),'--source-commit',a.source_commit,'--output',str((a.output/name).resolve())]
        with (a.output/(name+'.log')).open('x') as log:r=subprocess.run(command,cwd=ROOT,stdout=log,stderr=subprocess.STDOUT)
        if r.returncode:raise RuntimeError((name,r.returncode))
        cmd=[sys.executable,'tools/cryptid_contract_preservation.py','--before',str(before),'--after',str(a.output/name),'--output',str(a.output/(name+'-score.json'))]
        scored=subprocess.run(cmd,cwd=ROOT);rows.append({'cohort':name,'run_sha256':sha(a.output/name/'run.json'),'score_sha256':sha(a.output/(name+'-score.json')),'returncode':scored.returncode,'semantic_failed':read(a.output/(name+'-score.json'))['counts']['failed']});print(name,scored.returncode,flush=True)
    save(a.output/'prior-preservation.json',{'rows':rows,'source_commit':a.source_commit})
    if any(r['returncode'] or r['semantic_failed'] for r in rows):raise SystemExit(2)
if __name__=='__main__':
    p=argparse.ArgumentParser();p.add_argument('--implementation',type=Path,required=True);p.add_argument('--source-commit',required=True);p.add_argument('--output',type=Path,required=True);main(p.parse_args())
